		return modelcatalog.SurfaceAgentOpenAI, nil
	case "anthropic":
		return modelcatalog.SurfaceAgentAnthropic, nil
	default:
		return "", fmt.Errorf("config: cannot resolve model reference for provider type %q", providerType)
	}
}

// envVarPattern matches ${VAR_NAME} patterns.
var envVarPattern = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)\}`)

// expandEnvVars replaces ${VAR} patterns with environment variable values.
func expandEnvVars(s string) string {
	return envVarPattern.ReplaceAllStringFunc(s, func(match string) string {
		varName := strings.TrimSuffix(strings.TrimPrefix(match, "${"), "}")
		if val, ok := os.LookupEnv(varName); ok {
			return val
		}
		return match // leave unexpanded if not set
	})
}

// Save serializes the config to YAML bytes.
func (c *Config) Save() ([]byte, error) {
	// #nosec G117 -- config persistence intentionally serializes configured credentials.
	return yaml.Marshal(c)
}

// Save is a package-level alias for Config.Save.
func Save(cfg *Config) ([]byte, error) {
	return cfg.Save()
}

// SaveToFile writes the config to a YAML file.
func SaveToFile(path string, cfg *Config) error {
	data, err := cfg.Save()
	if err != nil {
		return fmt.Errorf("config: marshaling: %w", err)
	}
	if err := os.WriteFile(path, data, 0600); err != nil {
		return fmt.Errorf("config: writing %s: %w", path, err)
	}
	return nil
}

// validateProviders checks configured provider entries. A config with no
// providers is still loadable because several CLI surfaces do not need a
// runtime provider.
func (c *Config) validateProviders() error {
	if len(c.Providers) == 0 {
		return nil
	}
	for name, pc := range c.Providers {
		if pc.Type == "openai-compat" {
			return fmt.Errorf("config: provider %q: type openai-compat is no longer supported; use openai, openrouter, lmstudio, llama-server, omlx, rapid-mlx, or ollama", name)
		}
		switch pc.Type {
		case "openai", "openrouter", "lmstudio", "llama-server", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai", "anthropic":
		default:
			return fmt.Errorf("config: provider %q has unknown type %q (use openai, openrouter, lmstudio, llama-server, omlx, luce, vllm, rapid-mlx, ollama, or anthropic)", name, pc.Type)
		}
		if providerUsesEndpoint(pc.Type) {
			for i, endpoint := range pc.Endpoints {
				if endpoint.BaseURL == "" {
					return fmt.Errorf("config: provider %q endpoint %d: base_url is required", name, i+1)
				}
			}
		}
		if (pc.Type == "openai" || pc.Type == "openrouter" || pc.Type == "anthropic") && pc.APIKey == "" {
			return fmt.Errorf("config: provider %q (%s): api_key is required", name, pc.Type)
		}
	}
	return nil
}

package fizeau_test

import (
	"os"
	"path/filepath"
	"testing"
)

// TestMain isolates the agent_test package from the developer's live
// $HOME/.config/fizeau/config.yaml. Without this, calls like
// agent.New(agent.ServiceOptions{}) auto-load the user's real config —
// which has caused verify-worktree gates at older base revisions to fail
// when the live config contains provider types that revision didn't yet
// know about (agent-27806ad5).
//
// Per-test t.Setenv("HOME", ...) calls still take precedence for tests
// that need to plant a specific config on disk.
func TestMain(m *testing.M) {
	os.Exit(runTests(m))
}

func runTests(m *testing.M) int {
	tmp, err := os.MkdirTemp("", "agent-test-home-")
	if err != nil {
		panic(err)
	}
	defer os.RemoveAll(tmp)

	os.Setenv("HOME", tmp)
	os.Setenv("XDG_CONFIG_HOME", filepath.Join(tmp, ".config"))

	return m.Run()
}

